<?php
declare(strict_types=1); require_once __DIR__.'/../app/bootstrap.php'; require_admin();$pdo=db();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$id]);$order=$s->fetch();if(!$order){http_response_code(404);exit('Pedido não encontrado.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$new=(string)($_POST['status']??'');$allowed=['pending','confirmed','preparing','shipped','completed','cancelled'];try{if(!in_array($new,$allowed,true))throw new RuntimeException();$pdo->beginTransaction();$s=$pdo->prepare('SELECT * FROM orders WHERE id=? FOR UPDATE');$s->execute([$id]);$order=$s->fetch();$old=$order['status'];if($old!==$new){if($new==='cancelled' && $old!=='cancelled' && (int)$order['stock_deducted']===1){$items=$pdo->prepare('SELECT product_id,quantity FROM order_items WHERE order_id=? AND product_id IS NOT NULL');$items->execute([$id]);foreach($items->fetchAll() as $it){$p=$pdo->prepare('SELECT stock_quantity FROM products WHERE id=? FOR UPDATE');$p->execute([$it['product_id']]);$pr=$p->fetch();if($pr){$before=(float)$pr['stock_quantity'];$after=$before+(float)$it['quantity'];$pdo->prepare('UPDATE products SET stock_quantity=? WHERE id=?')->execute([$after,$it['product_id']]);$pdo->prepare('INSERT INTO stock_movements(product_id,user_id,order_id,movement_type,quantity,stock_before,stock_after,reason) VALUES(?,?,?,\'sale_return\',?,?,?,?)')->execute([$it['product_id'],(int)current_user()['id'],$id,$it['quantity'],$before,$after,'Reposição por cancelamento do pedido '.$order['order_number']]);}}$pdo->prepare('UPDATE orders SET stock_deducted=0,cancelled_at=NOW() WHERE id=?')->execute([$id]);}
$pdo->prepare('UPDATE orders SET status=?,confirmed_at=IF(?=\'confirmed\',NOW(),confirmed_at),completed_at=IF(?=\'completed\',NOW(),completed_at) WHERE id=?')->execute([$new,$new,$new,$id]);$pdo->prepare('INSERT INTO order_status_history(order_id,user_id,old_status,new_status,note) VALUES(?,?,?,?,?)')->execute([$id,(int)current_user()['id'],$old,$new,trim((string)($_POST['note']??''))]);$pdo->commit();flash('Estado do pedido atualizado.');}else{$pdo->commit();flash('O pedido já tinha esse estado.');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('Não foi possível atualizar o pedido.','error');}redirect('order.php?id='.$id);}
$s=$pdo->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$id]);$order=$s->fetch();$s=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$id]);$items=$s->fetchAll();$s=$pdo->prepare('SELECT h.*,u.name user_name FROM order_status_history h LEFT JOIN users u ON u.id=h.user_id WHERE h.order_id=? ORDER BY h.id DESC');$s->execute([$id]);$history=$s->fetchAll();layout_start('Detalhes do pedido');echo '<section class="panel"><div class="toolbar"><h2>'.e($order['order_number']).'</h2><a class="btn secondary" href="orders.php">Voltar aos pedidos</a></div><div class="form-grid"><p><strong>Cliente:</strong> '.e($order['customer_name']).'</p><p><strong>NIF:</strong> '.e($order['customer_nif']?:'—').'</p><p><strong>Telefone:</strong> '.e($order['customer_phone']).'</p><p><strong>Email:</strong> '.e($order['customer_email']?:'—').'</p><p><strong>Entrega:</strong> '.e($order['delivery_address']?:'—').'</p><p><strong>Data:</strong> '.e($order['ordered_at']).'</p></div><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Quantidade</th><th>Preço unitário</th><th>Subtotal</th></tr></thead><tbody>';foreach($items as $it)echo '<tr><td>'.e($it['product_name']).'</td><td>'.e($it['quantity']).' '.e($it['unit']).'</td><td>'.e(money($it['unit_price'])).'</td><td>'.e(money($it['subtotal'])).'</td></tr>';echo '</tbody></table></div><div style="text-align:right;margin-top:18px"><p>Subtotal: <strong>'.e(money($order['subtotal'])).'</strong></p><p>Entrega: <strong>'.e(money($order['delivery_fee'])).'</strong></p><p>Desconto: <strong>'.e(money($order['discount'])).'</strong></p><h2>Total: '.e(money($order['total'])).'</h2></div></section><section class="panel"><h2>Atualizar estado</h2><form method="post">'.csrf_field().'<div class="form-grid"><div class="field"><label>Estado</label><select name="status">';foreach(['pending'=>'Pendente','confirmed'=>'Confirmado','preparing'=>'Em preparação','shipped'=>'Enviado','completed'=>'Concluído','cancelled'=>'Cancelado'] as $k=>$v)echo '<option value="'.e($k).'"'.($order['status']===$k?' selected':'').'>'.e($v).'</option>';echo '</select></div><div class="field"><label>Observação</label><input name="note" maxlength="500"></div></div><button>Guardar estado</button></form></section><section class="panel"><h2>Histórico de estados</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Anterior</th><th>Novo</th><th>Responsável</th><th>Nota</th></tr></thead><tbody>';foreach($history as $h)echo '<tr><td>'.e($h['created_at']).'</td><td>'.e($h['old_status']?:'—').'</td><td>'.e($h['new_status']).'</td><td>'.e($h['user_name']?:'—').'</td><td>'.e($h['note']).'</td></tr>';if(!$history)echo '<tr><td colspan="5" class="empty">Sem histórico registado.</td></tr>';echo '</tbody></table></div></section>';layout_end();
